});

const resp = await client.chat.completions.create({
  model: "deepseek-v4-pro",
  messages: [{ role: "user", content: "Explain B-trees vs LSM-trees for an SRE interview." }],
  temperature: 0.3,
});

console.log(resp.choices[0].message.content);

